  "security.problems.presentation.t109.ransom-precursor.title": "Ransomware preparation detected",
  "security.problems.presentation.t109.ransom-precursor.what": "Host {host}. A host ran a command to destroy backups, disable recovery or stop backup services.",
  "security.problems.presentation.t109.ransom-precursor.why": "Ransomware often destroys recovery options before encrypting files.",
  "security.problems.presentation.t109.ransom-precursor.next": "Immediately check the host and command initiator. If unauthorized, isolate the host, restrict the account and protect offline backups.",
  "security.problems.presentation.t109.ransom-precursor.limitation": "A command or script was observed; successful backup deletion and encryption are not proven.",
  "security.problems.presentation.audit_category.8272": "System",
  "security.problems.presentation.audit_category.8273": "Logon/Logoff",
  "security.problems.presentation.audit_category.8274": "Object Access",
  "security.problems.presentation.audit_category.8275": "Privilege Use",
  "security.problems.presentation.audit_category.8276": "Detailed Tracking",
  "security.problems.presentation.audit_category.8277": "Policy Change",
  "security.problems.presentation.audit_category.8278": "Account Management",
  "security.problems.presentation.audit_category.8279": "DS Access",
  "security.problems.presentation.audit_category.8280": "Account Logon",
  "security.problems.presentation.audit_category.logon": "Logon",
  "security.problems.presentation.t109.security-log-cleared.title": "Security log cleared",
  "security.problems.presentation.t109.security-log-cleared.what": "{actor} cleared the security log on {computer} at {time}.",
  "security.problems.presentation.t109.security-log-cleared.why": "Clearing the log can hide an attack and interrupt SLI observation.",
  "security.problems.presentation.t109.security-log-cleared.next": "1) Ask {actor} why this was done. 2) If nobody confirms it, treat the computer as compromised: reset administrator passwords and review “Domain changes” for the day before the log was cleared.",
  "security.problems.presentation.t109.security-log-cleared.next_without_names": "1) Ask the administrators why the log was cleared. 2) If nobody confirms it, reset administrator passwords and review Domain changes for the day before the log was cleared.",
  "security.problems.presentation.t109.security-log-cleared.limitation": "The log clear is confirmed; the initiator intent needs investigation.",
  "security.problems.presentation.t109.audit-disabled.title": "Auditing was turned off on a computer",
  "security.problems.presentation.t109.audit-disabled.what": "{actor} turned off auditing of {category} on {computer} at {time}.",
  "security.problems.presentation.t109.audit-disabled.why": "An attacker may disable auditing before theft or encryption.",
  "security.problems.presentation.t109.audit-disabled.next": "1) Restore the setting: in SLI, “Agents” → computer → “Audit”. 2) Ask {actor} why it was changed.",
  "security.problems.presentation.t109.audit-disabled.next_without_names": "Restore the audit setting in the computer's details on the Agents page.",
  "security.problems.presentation.t109.audit-disabled.limitation": "The audit change is confirmed; approved maintenance may also cause it.",
  "security.problems.presentation.t109.agent-tamper.title": "The SLI agent was stopped or disabled",
  "security.problems.presentation.t109.agent-tamper.what": "The agent service on {computer} was stopped at {time}; startup changed by {actor}.",
  "security.problems.presentation.t109.agent-tamper.why": "Loss of observation may precede a fast attack.",
  "security.problems.presentation.t109.agent-tamper.next": "1) Start the `SLIAgentNet` service on the computer. 2) If you did not stop it, check Domain changes for {actor}.",
  "security.problems.presentation.t109.agent-tamper.next_without_names": "1) Start the SLIAgentNet service on the computer. 2) If the stop was unplanned, review Domain changes.",
  "security.problems.presentation.t109.agent-tamper.limitation": "A deletion command proves an attempt. Event 7045 proves disabled installation, not service deletion.",
  "security.problems.presentation.t109.agent-silenced.title": "SLI delivery stopped after a dangerous event",
  "security.problems.presentation.t109.agent-silenced.what": "Host {host}. Event delivery is overdue despite recent authenticated contact, following log clearing, audit removal or ransomware preparation.",
  "security.problems.presentation.t109.agent-silenced.why": "Observation was lost during a suspicious sequence.",
  "security.problems.presentation.t109.agent-silenced.next": "Urgently inspect the host through an independent channel, its services and logs. Protect backups and isolate the host if an attack is confirmed.",
  "security.problems.presentation.t109.agent-silenced.limitation": "Recent agent contact does not establish overall host health. Ordinary C08/C10 silence does not create this signal.",
  "security.problems.presentation.t109.file-ransom-fast.title": "Rapid mass file changes",
  "security.problems.presentation.qw.file-ransom.title": "Mass file changes",
  "security.problems.presentation.qw.file-ransom.next": "Check the account and folder. Stop the process.",
  "security.problems.presentation.file_ransom_quantity": "{files} files in {minutes} min",
  "security.problems.presentation.file_ransom_next_named": "Check the account {actor} and folder {folder}. Stop the process.",
  "security.problems.presentation.t109.file-ransom-fast.what": "Host {host}. Confirmed writes or deletions crossed the fast policy threshold: by default 30 distinct files in 30 seconds.",
  "security.problems.presentation.t109.file-ransom-fast.why": "Machine-speed changes require investigation before encryption spreads.",
  "security.problems.presentation.t109.file-ransom-fast.next": "Check the account, process and files. For unauthorized changes, isolate the source and temporarily restrict share writes.",
  "security.problems.presentation.t109.file-ransom-fast.limitation": "Encryption is not proven. The existing 100 files in 300 seconds threshold continues separately.",
  "security.problems.presentation.t109.mass-file-read.title": "Mass file reads or read access checks",
  "security.problems.presentation.t109.mass-file-read.what": "Host {host}. One account crossed the policy threshold: by default 200 distinct files or 10 distinct shares in 5 minutes.",
  "security.problems.presentation.t109.mass-file-read.why": "Mass access may precede data theft and extortion.",
  "security.problems.presentation.t109.mass-file-read.next": "Check the account, access source and approved exports. Restrict suspicious accounts and investigate outbound transfers; exclude approved backup accounts through policy.",
  "security.problems.presentation.t109.mass-file-read.limitation": "4663 records access; 5145 records a read access check. Transferred volume and exfiltration are not proven.",

