  // pages:security — keys of this area go right below this line
  "security.problems.presentation.qw.password-brute-force.title": "Password guessing against an account",
  "security.problems.presentation.qw.password-brute-force.what": "{quantity} to {account} from {source} since {time}.",
  "security.problems.presentation.qw.password-brute-force.why": "These attempts may indicate someone is trying to gain access to your systems.",
  "security.problems.presentation.qw.password-brute-force.next": "1) Check whether the user is making mistakes (a password change or an old device). 2) If the source is unfamiliar, block it on the firewall. 3) Change the account password.",
  "security.problems.presentation.qw.password-spray.title": "One source tries many accounts",
  "security.problems.presentation.qw.password-spray.what": "Failed sign-ins to {quantity} from {source} since {time}.",
  "security.problems.presentation.qw.password-spray.why": "These attempts may indicate someone is trying to gain access to your systems.",
  "security.problems.presentation.qw.password-spray.next": "1) Block the source on the firewall. 2) Open the list of affected accounts and check for a successful sign-in from the same address.",
  "security.problems.presentation.qw.password-success.title": "Sign-in succeeded after password guessing",
  "security.problems.presentation.qw.password-success.what": "{account} signed in from {source} at {time} after {quantity} from the same source.",
  "security.problems.presentation.qw.password-success.why": "These attempts may indicate someone is trying to gain access to your systems.",
  "security.problems.presentation.qw.password-success.next": "1) Change the account password immediately. 2) End its sessions. 3) Check Domain changes for its actions after the sign-in.",
  "security.problems.presentation.spray_title": "Passwords tried across several accounts",
  "security.problems.presentation.spray_object": "{source} ({account_quantity})",
  "security.problems.presentation.spray_threshold_title": "Sign-in attempts from {source} against {account_quantity} · {attempt_quantity}",
  "security.problems.presentation.queue_spray_title": "Sign-ins from {source} · {account_quantity} · {attempt_quantity}",
  "security.problems.presentation.spray_threshold_what": "One address produced failed sign-ins for multiple accounts within the rule window.",
  "security.problems.presentation.spray_campaign_title": "Password spray · {address_quantity} · {account_quantity} · {attempt_quantity}",
  "security.problems.presentation.spray_campaign_what": "Several addresses attempted to sign in to multiple accounts.",
  "security.problems.presentation.spray_campaign_success_what": "One of the addresses successfully signed in after failed sign-in attempts.",
  "security.problems.presentation.spray_threshold_success_what": "A successful sign-in from the same address followed failed sign-ins against that account.",
  "security.problems.presentation.spray_what": "One source attempted to sign in to five or more accounts within ten minutes. One or two attempts per account can indicate an automated list attack; regular intervals are supporting evidence.",
  "security.problems.presentation.spray_success_title": "A successful sign-in followed a password spray",
  "security.problems.presentation.spray_success_what": "After repeated failures, the same source successfully signed in to an attacked account. An attacker may have gained access.",
  "security.problems.presentation.spray_success_next": "Check the successful sign-in. If unexpected, isolate the source, end its sessions and reset the password from a trusted computer.",
  "security.problems.presentation.kerberoasting_title": "An account requested tickets for many services",
  "security.problems.presentation.kerberoasting_what": "{account} requested tickets for {count} services in {minutes} min from {source}.",
  "security.problems.presentation.kerberoasting_observed": "Source {source} requested RC4 tickets for {count} different service accounts within {seconds} seconds — possible Kerberoasting.",
  "security.problems.presentation.kerberoasting_why": "Weak passwords can be recovered from the tickets, granting the services' permissions.",
  "security.problems.presentation.kerberoasting_next": "1) Ask the account owner whether they ran a check. 2) If not, change the account password. 3) Change the passwords of the service accounts in the list; set long passwords for them.",
  "security.problems.presentation.asrep_title": "Ticket requested for an account without pre-authentication",
  "security.problems.presentation.asrep_what": "A ticket for {account} was issued without pre-authentication, requested from {source} at {time}.",
  "security.problems.presentation.asrep_observed": "Source {source} obtained a ticket for account {account} without pre-authentication — possible AS-REP roasting.",
  "security.problems.presentation.asrep_why": "The password can be guessed offline without further failed sign-ins or account lockouts.",
  "security.problems.presentation.asrep_next": "1) Clear the account option \"Do not require Kerberos preauthentication\". 2) Change its password.",
  "security.problems.presentation.preauth_title": "Kerberos pre-authentication is disabled on an account",
  "security.problems.presentation.preauth_what": "The AD snapshot shows a user with DONT_REQ_PREAUTH enabled. This is an unsafe setting, not proof of an attack.",
  "security.problems.presentation.preauth_why": "Knowing the account name is enough to obtain material for offline password guessing.",
  "security.problems.presentation.preauth_next": "Clear 'Do not require Kerberos preauthentication' in account properties. Check application compatibility and refresh the AD snapshot.",
  "security.problems.presentation.fanout_title": "One account rapidly signed in to several computers",
  "security.problems.presentation.fanout_what": "One account successfully signed in through the network or RDP to several computers in a short period — possible lateral movement.",
  "security.problems.presentation.fanout_observed": "Account {account} successfully signed in through the network or RDP to {count} different computers within {seconds} seconds — possible lateral movement.",
  "security.problems.presentation.fanout_why": "A stolen account may be used to rapidly access other computers.",
  "security.problems.presentation.fanout_next": "Ask the account owner whether these sign-ins were planned. If unexpected, end the sessions, isolate affected computers and reset the password. Add known service accounts to policy exclusions.",
  "security.problems.presentation.privilege_title": "An account was added to an administrators group",
  "security.problems.presentation.privilege_what": "{actor} added {member} to {group} at {time}.",
  "security.problems.presentation.privilege_new_what": "An account was created and added to a privileged group within ten minutes — possible attacker persistence.",
  "security.problems.presentation.privilege_why": "The new permissions can allow control over the domain, accounts or backups.",
