  "reports.v2.ad.users.v2.intent.freshness_expectation": "Latest AD snapshot time; activity needs source confirmation for the selected window.",
  "reports.v2.ad.computers.v6.intent.question": "Which AD computers need attention in the selected scope?",
  "reports.v2.ad.computers.v6.intent.denominator": "Expected AD computer objects in the selected scope; a partial snapshot cannot confirm the population.",
  "reports.v2.ad.computers.v6.intent.freshness_expectation": "Time of the last confirmed AD computer snapshot.",
  "reports.v2.ad.computer-logons.intent.question": "Which logons to the selected computers were observed in the period?",
  "reports.v2.ad.computer-logons.intent.denominator": "Stored logon events for the selected computers and period.",
  "reports.v2.ad.computer-logons.intent.freshness_expectation": "The report reads the stored events in the requested window.",
  "reports.v2.ad.new-logon-pairs.intent.question": "Which user–computer pairs were first observed in the period compared with the baseline window?",
  "reports.v2.ad.new-logon-pairs.intent.denominator": "Expected logon sources in the selected domain × selected period and baseline window; history bounds do not prove collection continuity.",
  "reports.v2.ad.new-logon-pairs.intent.freshness_expectation": "Logon history, baseline window and current AD context freshness are checked separately.",
  "reports.v2.ad.gpo.v2.intent.question": "Which Group Policies need manual review in the selected domain?",
  "reports.v2.ad.gpo.v2.intent.denominator": "Expected GPOs and link, setting and permission sections in authorized domains; a partial snapshot does not prove a complete population.",
  "reports.v2.ad.gpo.v2.intent.freshness_expectation": "Time of the last confirmed GPO snapshot; a missing previous snapshot is explicit.",
  "reports.v2.security.events.chains.intent.question": "Which security actions were observed in the selected scope?",
  "reports.v2.security.events.chains.intent.denominator": "Expected Security sources and event categories × period; the percentage is unknown without confirmed continuity.",
  "reports.v2.security.events.chains.intent.freshness_expectation": "Confirmation of each source in the selected window; current semantic facts do not reconstruct gaps.",
  "reports.v2.security.problems.intent.question": "Which published problems need an analyst decision in the selected scope?",
  "reports.v2.security.problems.intent.denominator": "Applicable accepted rules × authorized subjects × processing windows; finding count is not the denominator.",
  "reports.v2.security.problems.intent.freshness_expectation": "Check result publication time is shown separately from source event time and data loading time.",
  "reports.v2.vpn.accounts.intent.question": "Which accounts have VPN access through explicitly configured AD groups?",
  "reports.v2.vpn.accounts.intent.denominator": "Explicit VPN groups and expected AD sections in authorized domains; gateway users do not substitute for this population.",
  "reports.v2.vpn.accounts.intent.freshness_expectation": "Confirmation of AD VPN membership, account and privilege sections is checked separately.",
  "reports.v2.vpn.connections.intent.question": "Which VPN sessions are confirmed in the selected period?",
  "reports.v2.vpn.connections.intent.denominator": "Expected Accounting sources × period; NPS, Windows and AD each need their own denominators and evidence.",
  "reports.v2.vpn.connections.intent.freshness_expectation": "Accounting, NPS, Windows and AD confirmations are separate; one branch's freshness does not transfer to another.",
