  "reports.v2.security.events.chains.limitations.persistence_observations": "History shows observations in the selected window, not reconstructed state or proof of persistence. The previous value is only a previous observation; it is unknown when ordering is ambiguous. Software updates may be legitimate.",
  "reports.v2.security.events.chains.limitations.persistence_linking": "4697 and 7045 are linked only for a unique pair with exactly matching DC, time, name, file, RunAs and start type. Linking does not prove one installation. Frequency counts object observations (an exact pair counts once), not installations. Unknown objects and events without current semantics are kept separate; initiator names do not prove identity.",
  "reports.v2.security.events.chains.limitations.persistence_coverage": "Source completeness is unverified. Cards describe the filtered bounded slice: new objects mean observed creation/installation in the window; rare paths/actions have frequency no higher than the threshold (default 1). Missing events do not prove no changes or execution. Task XML is never executed; unknown action and RunAs values are not reconstructed.",
