  "reports.v2.security.events.chains.limitations.revocation_candidate": "These are candidates, not proof of bypassing revocation. Consider replication, existing tokens and clock error (delays up to 60 s are marked separately). A 4624 on a DC does not prove an interactive human logon; 6272 is an NPS decision, not a VPN session.",
  "reports.v2.security.events.chains.limitations.revocation_coverage": "Source completeness is unverified. Matching uses only an exact SID in one domain and current semantics. Unknown identities and events without current semantics are shown separately without name matching. Absence of 4722 does not prove absence of re-enabling.",
  "reports.v2.security.events.chains.limitations.revocation_window": "The period selects disable/delete times. New authentication is searched within the selected window after revocation; cards describe the filtered bounded slice. Accounting shows old sessions spanning revocation separately; the last session observation may fall outside the authentication window. Continuation source is RADIUS Accounting; session completeness is retained separately.",
  "reports.v2.security.events.chains.limitations.revocation_accounting": "Accounting is unavailable, has no matched rows, or was not checked without exact anchors. Absence of continuing VPN sessions has not been established.",
  "reports.v2.security.events.chains.limitations.revocation_truncated": "The event, session or row limit was reached. Counts are lower bounds for the read slice; narrow the period.",
